-- 077: 项目申报资格预检、任务书版本、内部签署留痕和电子档案清单。
-- 内部签署仅记录系统内确认，不构成法律电子签章。
BEGIN;

ALTER TABLE "纵向项目申报"
    ADD COLUMN IF NOT EXISTS "申报计划编号" bigint;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'fk_纵向项目申报_申报计划'
    ) THEN
        ALTER TABLE "纵向项目申报"
            ADD CONSTRAINT "fk_纵向项目申报_申报计划"
            FOREIGN KEY ("申报计划编号") REFERENCES "纵向项目申报计划"("编号");
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "ix_纵向项目申报_申报计划"
    ON "纵向项目申报" ("申报计划编号");

CREATE TABLE IF NOT EXISTS "纵向项目申报预检查记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "纵向项目申报编号" integer REFERENCES "纵向项目申报"("编号") ON DELETE SET NULL,
    "申报计划编号" bigint REFERENCES "纵向项目申报计划"("编号") ON DELETE SET NULL,
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "是否暂存" boolean NOT NULL DEFAULT false,
    "是否通过" boolean NOT NULL,
    "材料完整" boolean NOT NULL,
    "规则版本" varchar(30) NOT NULL DEFAULT '077',
    "检查结果" jsonb NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "ix_纵向项目申报预检查_申报"
    ON "纵向项目申报预检查记录" ("纵向项目申报编号", "建立时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_纵向项目申报预检查_申请人"
    ON "纵向项目申报预检查记录" ("申请人编号", "建立时间" DESC);

CREATE TABLE IF NOT EXISTS "纵向项目任务书" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "纵向项目立项编号" integer NOT NULL REFERENCES "纵向项目立项"("编号") ON DELETE CASCADE,
    "版本号" integer NOT NULL,
    "任务书标题" varchar(300) NOT NULL,
    "任务书内容" jsonb NOT NULL,
    "文件路径" varchar(1000),
    "文件校验和" varchar(128),
    "生成方式" varchar(20) NOT NULL DEFAULT '系统生成',
    "生成说明" varchar(2000),
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "生成人人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "生效时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_纵向项目任务书_版本" UNIQUE ("纵向项目立项编号", "版本号"),
    CONSTRAINT "ck_纵向项目任务书_版本" CHECK ("版本号" > 0),
    CONSTRAINT "ck_纵向项目任务书_生成方式" CHECK ("生成方式" IN ('系统生成','上传修订')),
    CONSTRAINT "ck_纵向项目任务书_状态" CHECK ("状态" IN ('草稿','待签署','签署中','已生效','已作废'))
);
CREATE INDEX IF NOT EXISTS "ix_纵向项目任务书_项目状态"
    ON "纵向项目任务书" ("纵向项目立项编号", "状态", "版本号" DESC);

CREATE TABLE IF NOT EXISTS "纵向项目任务书签署" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "任务书编号" bigint NOT NULL REFERENCES "纵向项目任务书"("编号") ON DELETE CASCADE,
    "签署人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "签署角色" varchar(50) NOT NULL,
    "签署方式" varchar(20) NOT NULL DEFAULT '内部确认',
    "签署声明" varchar(300) NOT NULL DEFAULT '本人确认已阅读任务书内容。本记录仅作为科研管理系统内部确认留痕，不构成法律电子签章。',
    "状态" varchar(20) NOT NULL DEFAULT '待签署',
    "签署说明" varchar(2000),
    "请求时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "确认时间" timestamp without time zone,
    CONSTRAINT "uq_纵向项目任务书签署_人员角色" UNIQUE ("任务书编号", "签署人编号", "签署角色"),
    CONSTRAINT "ck_纵向项目任务书签署_方式" CHECK ("签署方式" = '内部确认'),
    CONSTRAINT "ck_纵向项目任务书签署_状态" CHECK ("状态" IN ('待签署','已确认','已拒绝','已撤回'))
);
CREATE INDEX IF NOT EXISTS "ix_纵向项目任务书签署_待办"
    ON "纵向项目任务书签署" ("签署人编号", "状态", "请求时间" DESC);

CREATE TABLE IF NOT EXISTS "纵向项目电子档案清单" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "纵向项目立项编号" integer NOT NULL REFERENCES "纵向项目立项"("编号") ON DELETE CASCADE,
    "材料代码" varchar(50) NOT NULL,
    "材料名称" varchar(200) NOT NULL,
    "是否必需" boolean NOT NULL DEFAULT true,
    "要求说明" varchar(1000),
    "状态" varchar(20) NOT NULL DEFAULT '缺失',
    "关联档案材料编号" bigint REFERENCES "纵向项目档案材料"("编号") ON DELETE SET NULL,
    "核验说明" varchar(2000),
    "核验人编号" integer REFERENCES "人员"("编号"),
    "核验时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_纵向项目电子档案清单_项目代码" UNIQUE ("纵向项目立项编号", "材料代码"),
    CONSTRAINT "ck_纵向项目电子档案清单_状态" CHECK ("状态" IN ('缺失','已上传','已核验','不适用','作废'))
);
CREATE INDEX IF NOT EXISTS "ix_纵向项目电子档案清单_项目状态"
    ON "纵向项目电子档案清单" ("纵向项目立项编号", "状态", "是否必需");

INSERT INTO "系统迁移版本" ("编号", "版本", "脚本", "检查摘要", "应用时间")
VALUES (1, 77, '077_project_precheck_taskbook_archive.sql', '增加项目申报资格预检留痕、任务书版本及内部确认、电子档案清单', CURRENT_TIMESTAMP)
ON CONFLICT ("编号") DO UPDATE
SET "版本" = EXCLUDED."版本",
    "脚本" = EXCLUDED."脚本",
    "检查摘要" = EXCLUDED."检查摘要",
    "应用时间" = EXCLUDED."应用时间";

COMMIT;
